def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    r0 = min(r for r, c in fours)
    r1 = max(r for r, c in fours)
    c0 = min(c for r, c in fours)
    c1 = max(c for r, c in fours)

    for r, c in sixes:
        out[r][c] = 0

    sr0 = min(r for r, c in sixes)
    sr1 = max(r for r, c in sixes)
    sc0 = min(c for r, c in sixes)
    sc1 = max(c for r, c in sixes)

    # A compact T-shaped marker indicates a left-right reflection;
    # the wider cross-shaped marker indicates an up-down reflection.
    horizontal = (sc1 - sc0 + 1) <= (sr1 - sr0 + 1)

    if horizontal:
        # Prefer placing the reflected copy to the right; use the left if it
        # would extend beyond the grid.
        if 2 * c1 + 1 - c0 < w:
            axis_sum = 2 * c1 + 1
        else:
            axis_sum = 2 * c0 - 1
        for r, c in fours:
            cc = axis_sum - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        # Usually reflect below; a marker notably shifted to the right
        # indicates the copy belongs above.
        marker_c = (sc0 + sc1) / 2
        shape_c = (c0 + c1) / 2
        if marker_c > shape_c + 1:
            axis_sum = 2 * r0 - 1
        else:
            axis_sum = 2 * r1 + 1
        for r, c in fours:
            rr = axis_sum - r
            if 0 <= rr < h:
                out[rr][c] = 4

    return out
